head.b:skin:
/*
  Saeium Blogger Theme 1.5.0
  Original editorial design inspired by the structure of medium.com.
  No Medium marks, source code, articles or images are included.
*/
:root{--ink:#242424;--muted:#6b6b6b;--line:#e7e7e7;--paper:#fff;--cream:#f7f4ed;--accent:#1f7a4d;--max:1200px;--reading:680px}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--ink);background:var(--paper);font:16px/1.55 Arial,Helvetica,sans-serif}img{max-width:100%;height:auto}a{color:inherit;text-decoration:none}a:hover{text-decoration:underline}button,input{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.wrap{width:min(calc(100% - 48px),var(--max));margin-inline:auto}.sr-only{position:absolute;clip:rect(0,0,0,0);width:1px;height:1px;overflow:hidden}
.site-header{height:76px;border-bottom:1px solid var(--ink);background:var(--cream);position:relative;z-index:20}.site-header .wrap{height:100%;display:flex;align-items:center;gap:28px}.brand{margin-right:auto;min-width:0}.brand .Header{margin:0}.brand a{display:inline-flex;align-items:center}.brand h1,.brand .title{font:700 34px/1 Georgia,'Times New Roman',serif;letter-spacing:-.06em;margin:0}.brand img{display:block;max-width:190px;max-height:48px;object-fit:contain}.main-nav .widget{margin:0}.main-nav ul,.footer-links ul{display:flex;align-items:center;gap:28px;list-style:none;margin:0;padding:0}.main-nav a{font-size:14px;white-space:nowrap}.header-tools{display:flex;align-items:center;gap:12px}.icon-button{border:0;background:none;display:inline-grid;place-items:center;width:42px;height:42px;border-radius:50%;font-size:23px;line-height:1}.icon-button:hover{background:#e8e4dc}.header-cta,.pill{display:inline-flex;justify-content:center;align-items:center;border-radius:999px;background:var(--ink);color:#fff;padding:10px 20px;font-size:14px;line-height:1.3}.header-cta:hover,.pill:hover{background:#3e3e3e;text-decoration:none}.menu-toggle{display:none}.search-panel{display:none;position:absolute;top:75px;left:0;right:0;background:#fff;border-bottom:1px solid var(--line);box-shadow:0 12px 20px #0001}.search-panel.is-open{display:block}.search-panel form{display:flex;gap:12px;padding:18px 0}.search-panel input{flex:1;min-width:0;border:1px solid var(--line);border-radius:4px;padding:11px 14px}.search-panel button{border:0}
.hero{display:none;background:var(--cream);border-bottom:1px solid var(--ink)}.hero-inner{min-height:570px;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;padding:65px 0}.hero h2{font:400 clamp(72px,9.5vw,120px)/.87 Georgia,'Times New Roman',serif;letter-spacing:-.075em;max-width:800px;margin:0 0 45px}.hero p{font-size:22px;line-height:1.3;max-width:720px;margin:0 0 35px}.hero .pill{font-size:18px;padding:13px 34px}.hero .widget{width:100%}
.topic-strip{border-bottom:1px solid var(--line);padding:24px 0}.topic-strip .widget{display:flex;align-items:center;gap:20px}.topic-strip h2{font-size:13px;text-transform:uppercase;letter-spacing:.08em;white-space:nowrap;margin:0}.topic-strip ul{display:flex;gap:9px;overflow:auto;list-style:none;margin:0;padding:0;scrollbar-width:thin}.topic-strip li{flex:none}.topic-strip a,.tag-list a{display:inline-block;background:#f2f2f2;padding:7px 15px;border-radius:999px;font-size:13px;white-space:nowrap}.topic-strip a:hover,.tag-list a:hover{background:#e7e7e7;text-decoration:none}
.content-shell{display:grid;grid-template-columns:minmax(0,1fr) 315px;gap:68px;align-items:start;padding-top:46px;padding-bottom:90px}.content-main{min-width:0}.section-label{font-size:15px;font-weight:700;margin:0 0 20px}.trend-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:25px;border-bottom:1px solid var(--line);padding:0 0 38px;margin:0 0 34px;list-style:none;counter-reset:trend}.trend-list li{position:relative;padding-left:43px;counter-increment:trend}.trend-list li:before{content:counter(trend,decimal-leading-zero);position:absolute;left:0;top:0;color:#d1d1d1;font-size:26px;font-weight:700}.trend-list a{font-size:15px;line-height:1.3;font-weight:700}.trend-list small{display:block;color:var(--muted);font-size:12px;margin-top:9px}.archive-title{font-size:34px;line-height:1.2;letter-spacing:-.04em;margin:0 0 24px}.story-card{display:grid;grid-template-columns:minmax(0,1fr) 180px;gap:28px;padding:25px 0;border-bottom:1px solid var(--line)}.story-card:first-child{padding-top:0}.story-meta,.story-date{font-size:13px;color:var(--muted)}.story-meta{font-weight:600;color:var(--ink)}.story-title{font-size:24px;line-height:1.22;letter-spacing:-.025em;margin:8px 0}.story-snippet{font-size:16px;color:var(--muted);line-height:1.45;margin:0 0 14px;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}.story-image{width:180px;height:120px;object-fit:cover;background:#e9e9e9}.story-image.empty{display:grid;place-items:center;font:italic 26px Georgia,serif;color:#888}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:32px}.pager a{border:1px solid var(--line);border-radius:999px;padding:9px 18px;font-size:14px}
.sidebar{border-left:1px solid var(--line);padding-left:34px}.sidebar .widget{margin-bottom:44px}.sidebar h2{font-size:16px;margin:0 0 18px}.sidebar .Label ul{list-style:none;display:flex;flex-wrap:wrap;gap:8px;padding:0;margin:0}.sidebar .Label a{display:inline-block;background:#f2f2f2;border-radius:999px;padding:6px 13px;font-size:13px}.sidebar .HTML{font-size:14px;color:var(--muted)}.sidebar .HTML p{margin-top:0}
.post-page{max-width:var(--reading);margin:0 auto}.post-title{font-size:42px;line-height:1.19;letter-spacing:-.035em;margin:15px 0 18px}.post-subtitle{font-size:19px;color:var(--muted)}.post-byline{display:flex;gap:10px;align-items:center;color:var(--muted);font-size:14px;margin:22px 0}.post-byline strong{color:var(--ink)}.post-tools{display:flex;justify-content:flex-end;gap:14px;padding:15px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin:22px 0 36px}.post-tools button{border:0;background:none;color:var(--muted)}.post-body{font:20px/1.8 Georgia,'Times New Roman',serif;overflow-wrap:anywhere}.post-body p{margin:0 0 1.35em}.post-body h2{font:700 28px/1.3 Arial,Helvetica,sans-serif;margin:1.7em 0 .5em}.post-body h3{font:700 22px/1.35 Arial,Helvetica,sans-serif}.post-body blockquote{border-left:3px solid var(--ink);margin:1.5em 0;padding-left:22px;font-style:italic}.post-body a{text-decoration:underline}.post-body img{display:block;margin:25px auto}.post-labels{display:flex;flex-wrap:wrap;gap:8px;margin:40px 0}.post-comments{border-top:1px solid var(--line);padding-top:22px}.post-comments a{display:inline-block;border:1px solid var(--line);padding:8px 15px;border-radius:999px}
.site-footer{border-top:1px solid var(--ink);background:var(--cream);padding:28px 0}.site-footer .wrap{display:flex;align-items:center;justify-content:space-between;gap:24px}.footer-links ul{gap:16px;flex-wrap:wrap}.footer-links a,.credit{font-size:12px;color:var(--muted)}.credit a{text-decoration:underline}
.error-panel{padding:100px 0;max-width:680px}.error-panel h1{font:400 65px/.95 Georgia,serif}.notice{padding:28px;background:#f6f6f6;color:var(--muted)}
@media(max-width:900px){.content-shell{grid-template-columns:1fr;gap:34px}.sidebar{border-left:0;border-top:1px solid var(--line);padding:30px 0 0}.trend-list{gap:16px}.site-footer .wrap{align-items:flex-start;flex-direction:column}}
@media(max-width:680px){.wrap{width:min(calc(100% - 40px),var(--max))}.site-header{height:72px}.site-header .wrap{gap:8px}.brand h1,.brand .title{font-size:31px}.brand img{max-width:150px;max-height:42px}.main-nav{display:none;position:absolute;top:71px;left:0;right:0;background:var(--cream);border-bottom:1px solid var(--ink);padding:18px 20px}.main-nav.is-open{display:block}.main-nav ul{align-items:flex-start;flex-direction:column;gap:15px}.menu-toggle{display:inline-grid}.header-cta{display:none}.search-panel{top:71px}.hero-inner{min-height:650px;padding:70px 0}.hero h2{font-size:clamp(65px,18vw,80px);line-height:.9;letter-spacing:-.07em;margin-bottom:34px}.hero p{font-size:20px;line-height:1.35}.content-shell{padding-top:32px}.trend-list{grid-template-columns:1fr;gap:18px}.story-card{grid-template-columns:minmax(0,1fr) 96px;gap:14px}.story-image{width:96px;height:96px}.story-title{font-size:19px}.story-snippet{font-size:14px}.archive-title{font-size:26px}.post-title{font-size:32px;line-height:1.2}.post-body{font-size:18px;line-height:1.7}.topic-strip .widget{display:block}.topic-strip h2{margin-bottom:12px}}
@media(max-width:350px){.hero h2{font-size:60px}.story-card{grid-template-columns:minmax(0,1fr) 80px}.story-image{width:80px;height:80px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}

/* Saeium 1.1: editorial three-column shell */
:root{--rail:240px;--max:1180px}
.site-header{height:64px;position:sticky;top:0;z-index:80;background:#fff;border-color:var(--line)}
.site-header .wrap{width:100%;max-width:none;padding:0 24px;gap:18px}
.menu-toggle{display:inline-grid!important;flex:none;color:#555}.menu-toggle span{font-size:21px;line-height:1}
.brand{margin-right:6px}.brand h1,.brand .title{font-size:31px}.brand img{max-height:42px}
.header-search{width:min(300px,25vw);display:flex;align-items:center;gap:10px;background:#f7f7f7;border-radius:999px;padding:0 16px;color:#666;height:42px;margin-right:auto}
.header-search input{min-width:0;width:100%;border:0;background:transparent;outline:none;font-size:14px}
.header-tools{margin-left:auto}.search-toggle{display:none}.header-cta{padding:9px 18px}
.search-panel{top:63px}
.left-rail{position:fixed;top:64px;bottom:0;left:0;width:var(--rail);border-right:1px solid var(--line);background:#fff;z-index:70;overflow:auto;transition:width .2s ease,transform .2s ease}
.rail-scroll{padding:26px 18px}.rail-kicker,.rail-extras span{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:#999;display:block;margin:0 12px 14px}
.main-nav{display:block!important;position:static!important;background:transparent!important;border:0!important;padding:0!important}.main-nav ul{display:block!important;margin:0;padding:0;list-style:none}.main-nav li{margin:0 0 4px}.main-nav a,.rail-extras a{display:block;border-radius:8px;padding:10px 12px;font-size:15px;color:#505050}.main-nav a:hover,.rail-extras a:hover{background:#f5f5f5;text-decoration:none;color:var(--ink)}
.rail-extras{border-top:1px solid var(--line);margin-top:24px;padding-top:22px}.rail-extras a{font-size:13px}.nav-backdrop{display:none}
.page-frame{margin-left:var(--rail);transition:margin-left .2s ease}.page-frame .wrap{width:min(calc(100% - 64px),var(--max))}
body.nav-collapsed{--rail:88px}body.nav-collapsed .rail-kicker,body.nav-collapsed .rail-extras span{display:none}body.nav-collapsed .main-nav a,body.nav-collapsed .rail-extras a{font-size:11px;text-align:center;overflow:hidden;text-overflow:ellipsis;padding:12px 2px}body.nav-collapsed .rail-scroll{padding:20px 8px}
.hero{display:none;background:#f8f6f1;border-bottom:0}.hero-inner{min-height:0;padding:34px 0 28px}.hero h2{font-size:clamp(32px,4vw,52px);line-height:1.08;letter-spacing:-.055em;margin:0 0 8px;max-width:none}.hero p{font-size:16px;margin:0 0 15px}.hero .pill{font-size:13px;padding:8px 16px}
.topic-strip{padding:17px 0}.topic-strip h2{font-size:12px}
.content-shell{grid-template-columns:minmax(0,1fr) 300px;gap:48px;padding-top:36px;padding-bottom:70px}.content-main{min-width:0}.content-main .widget{max-width:720px;margin:auto}
.trend-list{gap:12px}.trend-list li{padding-left:30px}.trend-list li:before{font-size:19px}.trend-list a{font-size:14px}.trend-list small{font-size:11px}
.story-card{grid-template-columns:minmax(0,1fr) 150px;gap:18px}.story-image{width:150px;height:105px}.story-title{font-size:22px}.story-snippet{font-size:15px}.story-card-bottom{display:flex;align-items:center;justify-content:space-between;gap:10px}.story-save{border:0;background:transparent;color:#777;font-size:20px;padding:0 5px;line-height:1}.story-save.is-saved{color:var(--accent)}
.sidebar{padding-left:24px}.sidebar .widget{margin-bottom:32px}.sidebar h2,.sidebar-module h2{font-size:16px;margin:0 0 14px}.sidebar-module{border-top:1px solid var(--line);padding-top:25px;margin-bottom:32px}.recent-list{list-style:none;counter-reset:recent;margin:0;padding:0}.recent-list li{counter-increment:recent;position:relative;padding:0 0 16px 30px;line-height:1.3;font-size:14px;font-weight:700}.recent-list li:before{content:counter(recent,decimal-leading-zero);position:absolute;left:0;color:#c2c2c2;font-size:17px}.sidebar-more{font-size:13px;color:var(--accent)}.saved-module p{font-size:13px;color:var(--muted)}.saved-list{list-style:none;padding:0;margin:0}.saved-list li{font-size:13px;line-height:1.35;margin:0 0 12px}.sidebar-quick{border-top:1px solid var(--line);padding-top:18px;display:flex;flex-wrap:wrap;gap:10px 18px}.sidebar-quick a{font-size:12px;color:var(--muted)}
.post-page{max-width:680px}.post-title{font-size:42px}.post-tools{justify-content:space-between;align-items:center;color:var(--muted);font-size:13px}.post-tools-start,.post-tools-end{display:flex;align-items:center;gap:14px}.post-tools button,.post-tools a{font-size:13px;color:var(--muted);white-space:nowrap}.post-tools button:hover,.post-tools a:hover{color:var(--ink)}.post-tools .story-save{font-size:18px}.tool-sep{color:#bbb}.author-panel{display:flex;gap:20px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:30px 0;margin:45px 0}.author-avatar{background:#eaf2e9;color:var(--accent);width:58px;height:58px;border-radius:50%;display:grid;place-items:center;flex:none;font:italic 30px Georgia,serif}.eyebrow{font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}.author-panel h2{font-size:22px;margin:2px 0 5px}.author-panel p{font-size:14px;color:var(--muted);margin:0 0 8px}.author-panel a{font-size:13px;color:var(--accent)}.related-section{margin:35px 0}.related-section h2{font-size:22px}.related-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.related-list article{border:1px solid var(--line);padding:16px}.related-list article a{display:block;font-size:17px;line-height:1.3;font-weight:700;margin-top:8px}.post-comments{margin-top:35px}.post-comments h2{font-size:22px}
.site-footer{background:#fff;border-top:1px solid var(--line);padding:35px 0}.site-footer .wrap{display:grid;grid-template-columns:1fr 1fr;align-items:start;gap:22px}.footer-intro strong{font:700 25px/1 Georgia,serif;letter-spacing:-.05em}.footer-intro p{font-size:13px;color:var(--muted);margin:8px 0}.footer-links ul{gap:10px 18px}.footer-rss{display:flex;gap:18px}.footer-rss a{font-size:12px;color:var(--muted)}.site-footer #saeiumCredit{justify-self:end}
@media(max-width:1150px){.content-shell{grid-template-columns:minmax(0,1fr) 240px;gap:28px}.sidebar{padding-left:18px}.trend-list{grid-template-columns:1fr 1fr}}
@media(max-width:980px){.content-shell{display:block}.sidebar{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;border-left:0;border-top:1px solid var(--line);padding:28px 0 0;margin-top:44px}.sidebar .widget,.sidebar-module{margin:0}.sidebar-quick{align-self:start}.content-main .widget{max-width:720px}}
@media(max-width:760px){.site-header{height:60px}.site-header .wrap{padding:0 14px;gap:8px}.brand{margin-right:auto}.brand h1,.brand .title{font-size:28px}.header-search{display:none}.search-toggle{display:inline-grid}.header-cta{display:none}.search-panel{top:59px}.page-frame{margin-left:0}.page-frame .wrap{width:min(calc(100% - 36px),var(--max))}.left-rail{top:60px;width:250px;transform:translateX(-100%);box-shadow:12px 0 30px #0000}.nav-open .left-rail{transform:translateX(0);box-shadow:12px 0 30px #0002}.nav-open .nav-backdrop{display:block;position:fixed;inset:60px 0 0;background:#0005;z-index:65}.rail-kicker,.rail-extras span{display:block!important}.main-nav a,.rail-extras a{font-size:15px!important;text-align:left!important;padding:10px 12px!important}.rail-scroll{padding:24px 18px!important}.hero-inner{padding:25px 0 22px}.hero h2{font-size:36px;margin:0 0 9px}.hero p{font-size:15px}.topic-strip{padding:15px 0}.content-shell{padding-top:28px}.trend-list{grid-template-columns:1fr 1fr}.story-card{grid-template-columns:minmax(0,1fr) 96px}.story-image{width:96px;height:96px}.story-title{font-size:19px}.story-snippet{font-size:14px}.sidebar{grid-template-columns:1fr 1fr}.post-title{font-size:32px}.post-tools{gap:12px}.post-tools-start span:not(.tool-sep){display:none}.related-list{grid-template-columns:1fr 1fr}.site-footer .wrap{grid-template-columns:1fr}.site-footer #saeiumCredit{justify-self:start}}
@media(max-width:520px){.trend-list{grid-template-columns:1fr}.sidebar{grid-template-columns:1fr}.post-tools-start .tool-sep{display:none}.post-tools-end{gap:10px}.post-tools .story-save span{display:none}.related-list{grid-template-columns:1fr}.hero h2{font-size:33px}.story-snippet{-webkit-line-clamp:2}}
@media(prefers-reduced-motion:reduce){.left-rail,.page-frame{transition:none}}
body#layout .page-frame{margin:0!important}body#layout .left-rail{position:static!important;width:auto!important;transform:none!important;border:0!important}body#layout .site-header .wrap{display:block!important}body#layout .header-search,body#layout .menu-toggle,body#layout .rail-extras,body#layout .sidebar-module,body#layout .sidebar-quick{display:none!important}


/* Saeium 1.2: mobile reading experience, Pictogrammers Material Design Icons 7.4.47 */
.mdi-icon{width:24px;height:24px;display:inline-block;fill:currentColor;flex:none}.menu-toggle .mdi-icon{width:26px;height:26px}.header-saved{display:none}.header-search .mdi-icon{width:20px;height:20px}.search-form .mdi-icon{display:none}.recent-searches,.search-discovery{display:none}.mobile-discovery,.mobile-feed-tabs{display:none}.rail-extras a,.main-nav a{display:flex;align-items:center;gap:13px}.rail-extras a .mdi-icon,.main-nav a .mdi-icon{width:22px;height:22px;color:#777}.rail-extras a span{display:inline;font-size:15px;text-transform:none;letter-spacing:normal;color:inherit;margin:0}.nav-collapsed .rail-extras a span,.nav-collapsed .main-nav a span{display:none}.nav-collapsed .rail-extras a,.nav-collapsed .main-nav a{justify-content:center}.story-card{grid-template-areas:'author cover' 'copy cover' 'actions cover';grid-template-rows:auto 1fr auto}.story-author{grid-area:author;display:flex;align-items:center;gap:7px;min-width:0}.story-avatar{width:26px;height:26px;background:#f2f2f2;border-radius:50%;display:grid;place-items:center;color:#777;flex:none}.story-avatar .mdi-icon{width:15px;height:15px}.story-dot{color:#999}.story-copy{grid-area:copy;min-width:0}.story-cover{grid-area:cover;align-self:center}.story-card-bottom{grid-area:actions;position:relative}.story-read-time{font-size:12px;color:var(--muted)}.story-actions{display:flex;gap:12px;align-items:center}.story-actions button,.post-tools-end button{border:0;background:transparent;color:#777;display:inline-flex;align-items:center;justify-content:center;gap:5px;padding:4px;min-width:30px;min-height:30px}.story-actions button:hover,.post-tools-end button:hover{color:var(--ink)}.story-save .save-filled{display:none}.story-save.is-saved .save-filled{display:inline-block}.story-save.is-saved .save-outline{display:none}.story-options{position:absolute;right:0;bottom:100%;z-index:4;background:#fff;border:1px solid var(--line);box-shadow:0 8px 24px #0002;min-width:145px;padding:5px;border-radius:6px}.story-options[hidden]{display:none}.story-options a,.story-options button{display:block;width:100%;text-align:left;background:none;border:0;padding:9px 10px;font-size:13px}.story-options a:hover,.story-options button:hover{background:#f5f5f5;text-decoration:none}.post-tools-end .mdi-icon{width:20px;height:20px}
