/* Saeium 1.4: aligned desktop footer, response action, native threaded replies */
.site-footer{padding:0;background:#fff;border-top:1px solid var(--line)}
.site-footer .wrap{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:'intro links' 'shortcuts shortcuts' 'credit credit';column-gap:46px;row-gap:0;align-items:start;padding-top:42px;padding-bottom:28px}
.footer-intro{grid-area:intro;min-width:0}.footer-intro strong{display:block;font:700 32px/1.1 Georgia,'Times New Roman',serif;letter-spacing:-.06em}.footer-intro p{font:15px/1.5 Arial,Helvetica,sans-serif;color:var(--muted);margin:9px 0 0}
.footer-links{grid-area:links;justify-self:end;align-self:start;padding-top:8px}.footer-links ul{display:flex;justify-content:flex-end;gap:28px;flex-wrap:wrap}.footer-links a{font-size:15px;color:var(--ink)}
.footer-rss{grid-area:shortcuts;display:flex;gap:30px;flex-wrap:wrap;border-top:1px solid var(--line);padding:24px 0;margin-top:33px}.footer-rss a{font-size:14px;color:var(--muted)}
.site-footer #saeiumCredit{grid-area:credit;justify-self:stretch;border-top:1px solid var(--line);padding-top:20px}.site-footer .credit{font-size:12px;line-height:1.5;color:var(--muted)}
.post-actions .post-comments-jump{display:inline-flex;align-items:center;gap:7px;background:#fff;border:1px solid var(--line);border-radius:999px;padding:9px 14px;min-height:40px;font-size:14px;line-height:20px;color:#666;text-decoration:none}.post-actions .post-comments-jump:hover{border-color:#777;background:#fafafa;color:var(--ink)}.post-comments-jump .mdi-icon{width:20px;height:20px}
.post-comments a{display:inline;border:0;padding:0;border-radius:0}.threaded-comments{margin:0 0 20px}#comment-holder{margin:0 0 22px}#comment-holder .comment-thread ol{list-style:none;margin:0;padding:0}#comment-holder .comment-thread li{list-style:none;margin:0;padding:20px 0;border-bottom:1px solid var(--line)}#comment-holder .comment-thread .comment-replies{margin:16px 0 0 30px;padding-left:18px;border-left:2px solid #e8e8e8}#comment-holder .comment-thread .comment-replies li{border-bottom:0;padding:14px 0}#comment-holder .comment{overflow-wrap:anywhere}#comment-holder .comment-header{font-size:14px;font-weight:700;color:var(--ink)}#comment-holder .comment-header a{color:var(--ink)}#comment-holder .comment-header .datetime,#comment-holder .comment-timestamp{display:block;font-size:12px;font-weight:400;color:var(--muted);margin-top:4px}#comment-holder .comment-content{font:16px/1.6 Arial,Helvetica,sans-serif;margin:12px 0;color:var(--ink)}#comment-holder .comment-actions{display:flex;align-items:center;gap:17px;flex-wrap:wrap;margin-top:10px}#comment-holder .comment-actions a,#comment-holder .comment-reply{font-size:13px;color:var(--muted);text-decoration:none}#comment-holder .comment-actions a:hover,#comment-holder .comment-reply:hover{text-decoration:underline;color:var(--ink)}#comment-holder .comment-actions .comment-like{font-size:13px}#comment-holder .avatar-image-container{float:left;margin-right:11px}#comment-holder .avatar-image-container img{width:36px;height:36px;border-radius:50%;object-fit:cover}#comment-holder .comment-block{min-width:0;overflow:hidden}#comment-holder .thread-count{font-size:13px;color:var(--muted)}.comment-like-template[hidden]{display:none!important}
@media(max-width:760px){.site-footer .wrap{grid-template-columns:1fr;grid-template-areas:'intro' 'links' 'shortcuts' 'credit';padding-top:30px;padding-bottom:25px}.footer-intro strong{font-size:28px}.footer-intro p{font-size:14px}.footer-links{justify-self:start;padding-top:0;margin-top:23px}.footer-links ul{justify-content:flex-start;gap:18px}.footer-links a{font-size:14px}.footer-rss{gap:12px 23px;margin-top:23px;padding:20px 0}.footer-rss a{font-size:13px}.site-footer #saeiumCredit{padding-top:18px}.post-actions .post-comments-jump{flex:none;padding:8px 12px;font-size:13px;min-height:40px}.post-actions .post-more span{display:none}#comment-holder .comment-thread .comment-replies{margin-left:16px;padding-left:12px}}
