.story-actions .story-comments{display:inline-flex;align-items:center;justify-content:center;gap:5px;min-width:32px;min-height:30px;padding:4px;color:#777;font-size:13px;line-height:1;text-decoration:none}.story-actions .story-comments:hover{color:var(--ink)}.story-comments .mdi-icon{width:20px;height:20px}
.threaded-comments ~ .comment-form{background:transparent;border:0;border-radius:0;padding:0;margin:0}.threaded-comments ~ .comment-form h3,.threaded-comments ~ .comment-form p{display:none}#comment-holder .comment-replybox-thread:not(:empty),#comment-holder .comment-replybox-single:not(:empty){background:#fafafa;border:1px solid var(--line);border-radius:10px;padding:12px;margin:18px 0}#comment-holder #comment-editor{display:block;width:100%;min-height:90px}#comment-holder .comment-header .user{font-style:normal;font-weight:700}
/* Saeium 1.5: Medium-inspired typography and Blogger following */
:root{--font-sans:'Inter','Helvetica Neue',Helvetica,Arial,sans-serif;--font-reading:'Source Serif Pro',Georgia,Cambria,'Times New Roman',serif}
body,button,input{font-family:var(--font-sans)}
.brand h1,.brand .title,.footer-intro strong{font-family:Georgia,'Times New Roman',serif}
.hero h2,.story-title,.archive-title,.post-title,.post-deck,.post-body h2,.post-body h3,.sidebar h2,.sidebar-module h2,.author-panel h2,.publication-panel h2,.related-section h2,.post-comments h2,.error-panel h1{font-family:var(--font-sans)}
.story-title{font-weight:700;letter-spacing:-.02em}.post-title{font-size:42px;line-height:1.24;letter-spacing:-.011em;font-weight:700}.post-deck{font-size:22px;line-height:1.3}.post-body{font-family:var(--font-reading);font-size:20px;line-height:1.6}.post-body h2,.post-body h3{font-weight:700;letter-spacing:-.02em}.post-body blockquote{font-family:var(--font-reading);line-height:1.6}
.footer-intro p,.comment-body,#comment-holder .comment-content{font-family:var(--font-sans)}
.follow-module{border-top:1px solid var(--line);padding-top:25px;margin-bottom:32px}.follow-module h2{font-size:18px;line-height:1.3;letter-spacing:-.02em;margin:0 0 8px}.follow-module p{font-size:14px;line-height:1.5;color:var(--muted);margin:0 0 16px}.follow-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid var(--ink);border-radius:999px;background:var(--ink);color:#fff;padding:9px 17px;font-size:14px;font-weight:600;line-height:1.2;text-decoration:none}.follow-button:hover{background:#414141;color:#fff;text-decoration:none}.follow-button .mdi-icon{width:18px;height:18px}.rail-follow-link{display:flex;align-items:center;gap:13px;border-radius:8px;padding:10px 12px;font-size:15px;color:#505050}.rail-follow-link:hover{background:#f5f5f5;text-decoration:none;color:var(--ink)}.rail-follow-link .mdi-icon{width:22px;height:22px;color:#777}.post-follow-blog{display:inline-flex;align-items:center;border:1px solid var(--ink);border-radius:999px;padding:6px 15px;font-size:13px;font-weight:600;line-height:1.35;margin-left:5px}.post-follow-blog:hover{background:var(--ink);color:#fff;text-decoration:none}.publication-panel .follow-button{margin-right:9px}.footer-rss .footer-follow{color:var(--ink);font-weight:600}
.nav-collapsed .rail-follow-link{justify-content:center;font-size:0;padding:12px 2px}.nav-collapsed .rail-follow-link span{display:none}
@media(max-width:980px){.follow-module{margin:0}}
@media(max-width:760px){.post-title{font-size:36px;line-height:1.15}.post-deck{font-size:19px}.post-body{font-size:20px;line-height:1.6}.rail-follow-link{font-size:16px!important;padding:11px 5px!important;border-radius:0}.nav-collapsed .rail-follow-link{justify-content:flex-start}.nav-collapsed .rail-follow-link span{display:inline!important}.follow-module{padding-top:24px}}
@media(max-width:350px){.post-title{font-size:33px}.post-body{font-size:19px}.post-byline{flex-wrap:wrap}.post-follow-blog{margin-left:48px}}
body#layout .follow-module{display:block!important}


/* TB:NEWS_INDEX:CSS:START */
/* TemaBlogger shared News Index v1.0.0. Theme color and font are inherited. */
.tbni{--tbni-accent:var(--red,#df1529);--tbni-ink:var(--ink,#25272a);--tbni-line:#e7e8eb;color:var(--tbni-ink);margin:26px 0 40px;font-family:inherit;min-width:0}
.tbni *{box-sizing:border-box}
.tbni[hidden],.tbni [hidden]{display:none!important}
.tbni a{color:inherit;text-decoration:none}
.tbni .tbni-breadcrumb{display:flex;gap:8px;align-items:center;color:#82858c;font-size:11px;margin-bottom:18px}
.tbni-breadcrumb a:hover{color:var(--tbni-accent)}
.tbni .tbni-heading{font-size:36px;font-weight:800;letter-spacing:-1.1px;line-height:1.2;margin:0 0 12px}
.tbni-intro{font-size:13px;line-height:1.8;color:#777b83;margin:0 0 26px;max-width:560px}
.tbni-intro:before{content:"";display:block;width:42px;height:4px;background:var(--tbni-accent);margin:18px 0;border-radius:2px}
.tbni .tbni-form{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) 118px;gap:14px;align-items:end;padding:20px;background:#f7f8fa;border:1px solid #eceef1;border-radius:10px;margin:0 0 18px}
.tbni-field{display:block;min-width:0;font-size:11px;font-weight:600}
.tbni-field>span{display:block;margin-bottom:8px}
.tbni-control{position:relative;display:flex;align-items:center;min-width:0}
.tbni-control>.tbni-icon{position:absolute;left:12px;width:19px;height:19px;pointer-events:none;color:#858994}
.tbni input,.tbni select,.tbni button{font-family:inherit;font-size:12px}
.tbni input,.tbni select{width:100%;min-width:0;max-width:100%;height:44px;border:1px solid #dfe2e7;border-radius:6px;background:#fff;color:var(--tbni-ink);padding:0 10px 0 39px;line-height:normal}
.tbni select{padding-right:25px;text-overflow:ellipsis}
.tbni input[type=date]{color-scheme:light}
.tbni .tbni-submit{height:44px;border:1px solid var(--tbni-accent);border-radius:6px;background:var(--tbni-accent);color:#fff;font-weight:600;display:flex;align-items:center;justify-content:center;gap:8px;cursor:pointer}
.tbni-icon{display:inline-block;width:20px;height:20px;fill:currentColor;flex-shrink:0;vertical-align:middle}
.tbni-channels{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;padding:1px 1px 12px;margin-bottom:12px}
.tbni-channels::-webkit-scrollbar{display:none}
.tbni .tbni-chip{flex-shrink:0;white-space:nowrap;border:1px solid #e3e5e9;border-radius:20px;padding:8px 14px;color:#676b73;background:#fff;cursor:pointer;font-size:11px;line-height:1.4}
.tbni .tbni-chip[aria-pressed=true]{border-color:var(--tbni-accent);color:var(--tbni-accent);background:color-mix(in srgb,var(--tbni-accent) 6%,white);font-weight:600}
.tbni-summary{display:flex;justify-content:space-between;gap:14px;align-items:center;border-bottom:1px solid var(--tbni-line);padding-bottom:16px;margin-bottom:24px}
.tbni .tbni-count{font-weight:700;font-size:14px;margin:0 0 4px}
.tbni-context{font-size:11px;line-height:1.6;color:#8a8d94;margin:0}
.tbni .tbni-reset{background:none;border:0;color:var(--tbni-accent);padding:8px 0 8px 8px;min-height:40px;cursor:pointer;font-size:11px;white-space:nowrap}
.tbni .tbni-day{margin-bottom:26px}
.tbni .tbni-date{display:flex;align-items:center;gap:9px;font-size:14px;font-weight:700;line-height:1.5;margin:0;padding:12px 14px;background:#f5f6f8;border-left:3px solid var(--tbni-accent);border-radius:0 5px 5px 0}
.tbni-date .tbni-icon{width:18px;height:18px;color:var(--tbni-accent)}
.tbni .tbni-row{display:grid;grid-template-columns:58px minmax(0,1fr) 132px;gap:18px;align-items:center;padding:21px 0;border-bottom:1px solid var(--tbni-line)}
.tbni-time{align-self:start;padding-top:3px;font-size:12px;font-weight:600;color:#858994;line-height:1.6;font-variant-numeric:tabular-nums}
.tbni-time small{display:block;font-size:9px;font-weight:400;letter-spacing:.4px;color:#a1a4aa;margin-top:2px}
.tbni-copy{min-width:0}
.tbni .tbni-category{display:inline-block;color:var(--tbni-accent);font-size:10px;font-weight:600;margin:0 0 7px;line-height:1.4}
.tbni .tbni-title{font-size:16px;font-weight:700;line-height:1.55;letter-spacing:-.15px;margin:0;overflow-wrap:anywhere}
.tbni-title a:hover{color:var(--tbni-accent)}
.tbni .tbni-photo{display:grid;place-items:center;aspect-ratio:16/10;align-self:start;overflow:hidden;border-radius:6px;background:#f0f1f4;color:#b2b5bc}
.tbni-photo img{display:block;width:100%;height:100%;object-fit:cover}
.tbni-photo>.tbni-icon{width:30px;height:30px}
.tbni-more-area{text-align:center;padding:4px 0}
.tbni-progress{color:#8a8d94;font-size:11px;line-height:1.6;margin:0 0 14px}
.tbni .tbni-more,.tbni .tbni-retry{display:inline-flex;justify-content:center;align-items:center;gap:10px;border:1px solid var(--tbni-accent);border-radius:6px;min-height:44px;background:#fff;color:var(--tbni-accent);padding:10px 24px;font-size:12px;font-weight:600;cursor:pointer}
.tbni button:disabled{opacity:.55;cursor:wait}
.tbni button:focus-visible,.tbni input:focus-visible,.tbni select:focus-visible,.tbni a:focus-visible{outline:2px solid var(--tbni-accent);outline-offset:3px}
.tbni .tbni-notice{padding:32px 20px;border:1px solid var(--tbni-line);background:#fafbfc;border-radius:8px;text-align:center;margin-bottom:22px}
.tbni-notice>.tbni-icon{width:36px;height:36px;color:#afb3bd;margin-bottom:8px}
.tbni .tbni-notice h2{font-size:17px;line-height:1.5;margin:0 0 8px}
.tbni .tbni-notice p{font-size:12px;line-height:1.8;color:#80848d;margin:0 0 16px}
.tbni .tbni-native-link{display:block;font-size:11px;color:#80848d;margin-top:14px;text-decoration:underline}
.tbni-loading .tbni-ghost{height:120px;border-bottom:1px solid var(--tbni-line);background:linear-gradient(90deg,#f4f5f7 0 9%,transparent 9% 13%,#f4f5f7 13% 75%,transparent 75%);margin:0 0 12px;opacity:.7}
.has-tb-news-index .tb-index-native{display:none}
@media(max-width:600px){
 .tbni{margin-top:22px}
 .tbni .tbni-heading{font-size:30px;letter-spacing:-.8px}
 .tbni-intro{font-size:12px;margin-bottom:22px}
 .tbni .tbni-form{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px 10px;padding:16px}
 .tbni .tbni-submit{grid-column:1/-1}
 .tbni input,.tbni select{font-size:11px;padding-left:32px}
 .tbni-control>.tbni-icon{left:9px;width:17px;height:17px}
 .tbni input[type=date]{padding-right:4px}
 .tbni .tbni-row{grid-template-columns:39px minmax(0,1fr) 86px;gap:10px;padding:18px 0}
 .tbni .tbni-title{font-size:13px;line-height:1.6;letter-spacing:-.1px}
 .tbni-time{font-size:10px}
 .tbni-time small{font-size:8px}
 .tbni .tbni-category{font-size:9px;margin-bottom:5px}
 .tbni .tbni-date{font-size:12px;padding:11px 10px}
 .tbni .tbni-count{font-size:13px}
 .tbni-context{font-size:10px}
 .tbni .tbni-photo{border-radius:5px}
}
@media(max-width:360px){.tbni .tbni-row{grid-template-columns:35px minmax(0,1fr) 72px;gap:8px}.tbni .tbni-title{font-size:12px}.tbni .tbni-form{padding:12px;gap:12px 8px}.tbni input,.tbni select{padding-left:28px}.tbni-control>.tbni-icon{left:7px;width:16px;height:16px}}
/* TB:NEWS_INDEX:CSS:END */

head.b:template-skin:
body#layout .site-header,body#layout .hero,body#layout .topic-strip,body#layout .content-shell,body#layout .site-footer{display:block!important;height:auto!important;min-height:0!important;position:static!important;background:#fff!important;padding:10px!important}
body#layout .wrap,body#layout .hero-inner{display:block!important;width:auto!important;min-height:0!important;padding:0!important}
body#layout .main-nav,body#layout .sidebar{display:block!important;position:static!important;border:0!important}
body#layout .content-shell{display:grid!important;grid-template-columns:minmax(0,2fr) minmax(250px,1fr)!important;gap:18px!important}
body#layout .section{padding:14px!important;margin:8px 0 18px!important;border:1px solid #d8dfda!important;border-radius:8px;background:#f8fbf8!important}
body#layout .section h4{font-size:14px!important;font-weight:700!important}
body#layout .widget{border:1px solid #e6e8e6!important;background:#fff!important;padding:10px!important;margin:8px 0!important}
body#layout .add_widget{display:none!important}

body.script:
//
  (function(){
    'use strict';
    var menu=document.querySelector('.menu-toggle'),nav=document.getElementById('main-nav'),backdrop=document.getElementById('nav-backdrop');
    var search=document.querySelector('.search-toggle'),panel=document.getElementById('search-panel');
    function mobile(){return window.matchMedia('(max-width: 760px)').matches;}
    function closeNav(){document.body.classList.remove('nav-open');if(menu)menu.setAttribute('aria-expanded',mobile()?'false':String(!document.body.classList.contains('nav-collapsed')));}
    if(menu&&nav){menu.setAttribute('aria-expanded',mobile()?'false':'true');menu.addEventListener('click',function(){if(mobile()){var opened=document.body.classList.toggle('nav-open');menu.setAttribute('aria-expanded',String(opened));}else{var collapsed=document.body.classList.toggle('nav-collapsed');menu.setAttribute('aria-expanded',String(!collapsed));try{localStorage.setItem('saeium-rail',collapsed?'collapsed':'open');}catch(e){}}});}
    if(backdrop)backdrop.addEventListener('click',closeNav);
    if(nav)nav.addEventListener('click',function(e){if(e.target.closest('a')&&mobile())closeNav();});
    if(!mobile()){try{if(localStorage.getItem('saeium-rail')==='collapsed'){document.body.classList.add('nav-collapsed');if(menu)menu.setAttribute('aria-expanded','false');}}catch(e){}}
    window.addEventListener('resize',closeNav);
    if(search&&panel)search.addEventListener('click',function(){var open=search.getAttribute('aria-expanded')!=='true';panel.classList.toggle('is-open',open);document.body.classList.toggle('search-open',open);search.setAttribute('aria-expanded',String(open));if(open){closeNav();renderRecent();document.getElementById('search-input').focus();}});
    document.addEventListener('keydown',function(e){if(e.key==='Escape'){closeNav();if(search&&panel){panel.classList.remove('is-open');document.body.classList.remove('search-open');search.setAttribute('aria-expanded','false');}}});
    function copyLink(button,url){var old=button.getAttribute('aria-label')||button.textContent;navigator.clipboard.writeText(url||location.href).then(function(){button.setAttribute('aria-label','Link copied');setTimeout(function(){button.setAttribute('aria-label',old);},1800);}).catch(function(){});}
    function renderRecent(){var box=document.querySelector('.recent-queries'),empty=document.querySelector('.recent-empty');if(!box)return;var list=[];try{list=JSON.parse(localStorage.getItem('saeium-recent-searches')||'[]');}catch(e){}box.innerHTML='';list.slice(0,5).forEach(function(q){var li=document.createElement('li'),a=document.createElement('a');a.href='/search?q='+encodeURIComponent(q);a.textContent=q;li.appendChild(a);box.appendChild(li);});if(empty)empty.hidden=list.length>0;}
    document.querySelectorAll('.search-form,.header-search').forEach(function(form){form.addEventListener('submit',function(){var input=form.querySelector('input[name=q]');if(!input||!input.value.trim())return;var q=input.value.trim(),list=[];try{list=JSON.parse(localStorage.getItem('saeium-recent-searches')||'[]');}catch(e){}list=[q].concat(list.filter(function(item){return item.toLowerCase()!==q.toLowerCase();})).slice(0,5);try{localStorage.setItem('saeium-recent-searches',JSON.stringify(list));}catch(e){}});});
    document.querySelectorAll('[data-feed-tab]').forEach(function(tab){tab.addEventListener('click',function(){var featured=tab.getAttribute('data-feed-tab')==='featured',list=document.querySelector('.story-list');if(list)list.classList.toggle('is-featured',featured);document.querySelectorAll('[data-feed-tab]').forEach(function(other){var active=other===tab;other.classList.toggle('is-active',active);other.setAttribute('aria-selected',String(active));});});});
    document.addEventListener('click',function(e){var more=e.target.closest('.story-more');document.querySelectorAll('.story-options').forEach(function(options){var show=more&&more.closest('.story-card')===options.closest('.story-card')&&options.hidden;options.hidden=!show;var toggle=options.parentElement.querySelector('.story-more');if(toggle)toggle.setAttribute('aria-expanded',String(show));});if(more)return;var copy=e.target.closest('.story-copy-link');if(copy){copyLink(copy,copy.getAttribute('data-story-url'));return;}var share=e.target.closest('.story-share');if(share){var url=share.getAttribute('data-story-url'),title=share.getAttribute('data-story-title');if(navigator.share)navigator.share({title:title,url:url}).catch(function(){});else copyLink(share,url);}});
    function readSaved(){try{return JSON.parse(localStorage.getItem('saeium-saved')||'[]');}catch(e){return [];}}
    function save(items){try{localStorage.setItem('saeium-saved',JSON.stringify(items));}catch(e){}}
    function renderSaved(){var items=readSaved();document.querySelectorAll('[data-save-url]').forEach(function(button){var active=items.some(function(item){return item.url===button.getAttribute('data-save-url');});button.classList.toggle('is-saved',active);button.setAttribute('aria-pressed',String(active));button.setAttribute('aria-label',active?'Remove saved story':'Save story');});var list=document.querySelector('[data-saved-stories]');if(list){list.innerHTML='';var intro=document.querySelector('.saved-intro');if(intro)intro.hidden=items.length>0;items.slice(0,5).forEach(function(item){var li=document.createElement('li'),a=document.createElement('a');a.href=item.url;a.textContent=item.title;li.appendChild(a);list.appendChild(li);});}}
    document.addEventListener('click',function(e){var button=e.target.closest('[data-copy-link]');if(button){copyLink(button,button.getAttribute('data-story-url'));return;}button=e.target.closest('[data-share-link]');if(button){if(navigator.share)navigator.share({title:document.title,url:location.href}).catch(function(){});else copyLink(button);return;}button=e.target.closest('[data-save-url]');if(button){var url=button.getAttribute('data-save-url'),title=button.getAttribute('data-save-title'),items=readSaved(),at=items.findIndex(function(item){return item.url===url;});if(at>=0)items.splice(at,1);else items.unshift({url:url,title:title});save(items.slice(0,30));renderSaved();}});
    renderSaved();
    function readCommentLikes(){try{return JSON.parse(localStorage.getItem('saeium-comment-likes')||'[]');}catch(e){return [];}}
    function renderCommentLikes(){var liked=readCommentLikes();document.querySelectorAll('button.comment-like[data-comment-id]').forEach(function(button){var active=liked.includes(button.getAttribute('data-comment-id'));button.classList.toggle('is-liked',active);button.setAttribute('aria-pressed',String(active));button.setAttribute('aria-label',active?'Unlike comment':'Like comment');var label=button.querySelector('span');if(label)label.textContent=active?'Liked':'Like';});}
    document.addEventListener('click',function(e){var button=e.target.closest('button.comment-like[data-comment-id]');if(!button)return;var id=button.getAttribute('data-comment-id'),liked=readCommentLikes(),at=liked.indexOf(id);if(at>=0)liked.splice(at,1);else liked.push(id);try{localStorage.setItem('saeium-comment-likes',JSON.stringify(liked));}catch(e){}renderCommentLikes();});
    renderCommentLikes();
    var nativeComments=document.getElementById('comment-holder'),likeTemplate=document.querySelector('.comment-like-template .comment-like');
    if(nativeComments&&likeTemplate){
      var addNativeLikes=function(){var added=false;nativeComments.querySelectorAll('.comment').forEach(function(comment,index){if(comment.querySelector('.comment-like'))return;var key=comment.id||comment.getAttribute('data-comment-id')||'comment-'+index;var target=comment.querySelector('.comment-actions')||comment.querySelector('.comment-footer')||comment.querySelector('.comment-block')||comment;var button=likeTemplate.cloneNode(true);button.setAttribute('data-comment-id',key);target.appendChild(button);added=true;});if(added)renderCommentLikes();};
      addNativeLikes();new MutationObserver(addNativeLikes).observe(nativeComments,{childList:true,subtree:true});
    }
    var postBody=document.querySelector('.post-page .post-body'),postDeck=document.querySelector('.post-deck'),readTime=document.querySelector('[data-reading-time]');
    if(postBody){var words=(postBody.textContent||'').trim().split(/\s+/).filter(Boolean).length;if(readTime)readTime.textContent=Math.max(1,Math.ceil(words/220))+' min read';if(postDeck){var first=Array.from(postBody.children).find(function(node){return node.tagName==='P'&&!node.querySelector('img')&&(node.textContent||'').trim().length>45;});if(first){postDeck.appendChild(first);postDeck.hidden=false;}}}
    var listen=document.querySelector('[data-listen]'),speech=null;
    if(listen){if(!('speechSynthesis' in window)||!window.SpeechSynthesisUtterance)listen.hidden=true;else listen.addEventListener('click',function(){var active=listen.getAttribute('aria-pressed')==='true';window.speechSynthesis.cancel();if(active){listen.setAttribute('aria-pressed','false');listen.querySelector('span').textContent='Listen';return;}var content=[document.querySelector('.post-title'),postDeck,postBody].filter(Boolean).map(function(el){return el.textContent.trim();}).join('. ');speech=new SpeechSynthesisUtterance(content);speech.lang=document.documentElement.lang||'en-US';speech.onend=speech.onerror=function(){listen.setAttribute('aria-pressed','false');listen.querySelector('span').textContent='Listen';};listen.setAttribute('aria-pressed','true');listen.querySelector('span').textContent='Stop';window.speechSynthesis.speak(speech);});}
    var postMore=document.querySelector('.post-more'),postOptions=document.querySelector('.post-options');if(postMore&&postOptions){postMore.addEventListener('click',function(){var open=postOptions.hidden;postOptions.hidden=!open;postMore.setAttribute('aria-expanded',String(open));});document.addEventListener('click',function(e){if(!e.target.closest('.post-action-wrap')){postOptions.hidden=true;postMore.setAttribute('aria-expanded','false');}});document.addEventListener('keydown',function(e){if(e.key==='Escape'){postOptions.hidden=true;postMore.setAttribute('aria-expanded','false');}});}
    function textOf(html){var div=document.createElement('div');div.innerHTML=html||'';return (div.textContent||'').replace(/\s+/g,' ').trim();}
    function postLink(entry){var alt=(entry.link||[]).find(function(link){return link.rel==='alternate';});return alt?alt.href:'';}
    function addStory(container,entry){var a=document.createElement('a');a.href=postLink(entry);a.textContent=entry.title&&entry.title.$t||'Untitled story';container.appendChild(a);}
    var needsFeed=document.querySelector('[data-recent-stories],[data-related-stories],.story-snippet[data-post-url]');
